import java.util.*;
import java.io.*;
import java.math.BigInteger;

public class FFT {
    private static final int MAX_SIZE = 1 << 20;
    private static final long MOD = 998244353L;
    private static final long W = 646L;
    private static final long[] W_ARR = new long[MAX_SIZE];
    private static final long[] W_INV_ARR = new long[MAX_SIZE];
    private static final long SIZE_INV;

    static {
        BigInteger modBI = BigInteger.valueOf(MOD);
        BigInteger wBI = BigInteger.valueOf(W);
        BigInteger sizeBI = BigInteger.valueOf(MAX_SIZE);
        W_ARR[0] = 1;
        W_INV_ARR[0] = 1;
        for (int i = 1; i < MAX_SIZE; i++) {
            W_ARR[i] = W_ARR[i - 1] * W % MOD;
            W_INV_ARR[i] = W_INV_ARR[i - 1] * W % MOD;
        }
        SIZE_INV = sizeBI.modInverse(modBI).longValue();
    }

    private FastScanner scanner;
    private PrintWriter writer;
    private boolean useSystemIO = true;

    private static class DataBuffer {
        private final long[] buffer = new long[MAX_SIZE];

        DataBuffer(long[] input) {
            for (int i = 0; i < input.length; i++) {
                buffer[i] = input[i];
            }
        }

        long[] transform(boolean forward) {
            return recursiveDFT(0, 1, forward);
        }

        private long[] recursiveDFT(int start, int step, boolean forward) {
            if (step == MAX_SIZE) {
                return new long[]{buffer[start]};
            }
            long[] even = recursiveDFT(start, step * 2, forward);
            long[] odd = recursiveDFT(start + step, step * 2, forward);
            int half = even.length;
            long[] result = new long[half * 2];
            for (int i = 0; i < half; i++) {
                long twiddle = forward ? W_ARR[i * step] : W_INV_ARR[i * step];
                result[i] = (even[i] + twiddle * odd[i]) % MOD;
            }
            for (int i = 0; i < half; i++) {
                long twiddle = forward ? W_ARR[i * step] : W_INV_ARR[i * step];
                result[half + i] = ((even[i] - twiddle * odd[i]) % MOD + MOD) % MOD;
            }
            return result;
        }
    }

    private long[] computeDFT(long[] input) {
        int n = MAX_SIZE;
        long[] output = new long[n];
        long wPower = 1;
        for (int i = 0; i < n; i++) {
            long x = 1;
            for (int j = 0; j < input.length; j++) {
                output[i] = (output[i] + input[j] * x) % MOD;
                x = x * wPower % MOD;
            }
            wPower = wPower * W % MOD;
        }
        return output;
    }

    private long[] exponentiate(long[] arr, int exponent) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] = modularExponentiation(arr[i], exponent);
        }
        return arr;
    }

    private long modularExponentiation(long base, int exp) {
        if (exp == 0) return 1;
        if ((exp & 1) == 1) return modularExponentiation(base, exp - 1) * base % MOD;
        long half = modularExponentiation(base, exp >> 1);
        return half * half % MOD;
    }

    private void process() {
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long[] values = new long[10];
        for (int i = 0; i < k; i++) {
            values[scanner.nextInt()] = 1;
        }
        long[] transformed = computeDFT(values);
        transformed = exponentiate(transformed, n / 2);
        DataBuffer buffer = new DataBuffer(transformed);
        transformed = buffer.transform(false);
        for (int i = 0; i < transformed.length; i++) {
            transformed[i] = transformed[i] * SIZE_INV % MOD;
        }
        long result = 0;
        for (long val : transformed) {
            result = (result + val * val) % MOD;
        }
        writer.println(result);
    }

    private void initialize() {
        try {
            if (useSystemIO) {
                scanner = new FastScanner(System.in);
                writer = new PrintWriter(System.out);
            } else {
                scanner = new FastScanner(new File("input.txt"));
                writer = new PrintWriter(new File("output.txt"));
            }
            process();
            writer.close();
        } catch (IOException exception) {
            exception.printStackTrace();
        }
    }

    private static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(File file) {
            try {
                reader = new BufferedReader(new FileReader(file));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }

    public static void main(String[] args) {
        new FFT().initialize();
    }
}
